<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'&&!defined('KHUSHRANG_INTERNAL')){http_response_code(404);exit;}
function connection_rows(PDO $db,string $kind,?int $limit=null): array {$q=$db->prepare('SELECT id,payload FROM records WHERE kind=? ORDER BY created_at DESC'.($limit!==null?' LIMIT '.max(1,min(1000,$limit)):''));$q->execute([$kind]);return array_map(static fn($r)=>array_merge(json_decode($r['payload'],true),['_record_id'=>$r['id']]),$q->fetchAll());}
function connection_worker_command(): string {$prefix='';foreach(['KHUSHRANG_CONFIG','KHUSHRANG_ENV_FILE'] as $name){$value=getenv($name);if($value!==false&&$value!=='')$prefix.=$name.'='.escapeshellarg($value).' ';}return $prefix.'php '.escapeshellarg(__DIR__.'/integration-worker.php');}
function connection_put(PDO $db,string $id,string $kind,array $data): void {$q=$db->prepare('INSERT INTO records(id,kind,payload) VALUES(?,?,?) ON DUPLICATE KEY UPDATE payload=IF(kind=VALUES(kind),VALUES(payload),payload),updated_at=UTC_TIMESTAMP()');$q->execute([$id,$kind,json_encode($data,JSON_THROW_ON_ERROR)]);$q=$db->prepare('SELECT kind FROM records WHERE id=?');$q->execute([$id]);if($q->fetchColumn()!==$kind)throw new IntegrationError('System record ID is occupied by another record type.',409);}
function connection_key(PDO $db,array $config,bool $create=false): string {
 $directory=$config['private_directory']??dirname(getenv('KHUSHRANG_CONFIG')?:khushrang_config_path(__DIR__));$path=$directory.'/integration.key';
 if(!is_file($path)&&$create){$q=$db->query("SELECT COUNT(*) FROM records WHERE kind='integration_webhook'");if((int)$q->fetchColumn()>0)throw new IntegrationError('The private integration.key is missing. Restore it from backup before editing webhook credentials.',503);$file=@fopen($path,'x');if($file){chmod($path,0600);fwrite($file,base64_encode(random_bytes(32)));fclose($file);}}
 $encoded=@file_get_contents($path);$key=$encoded!==false?base64_decode(trim($encoded),true):false;if($key===false||strlen($key)!==32)throw new IntegrationError('Cannot read the private webhook encryption key. Ensure khushrang-private is writable for first setup, or restore integration.key.',503);return $key;
}
function connection_encrypt(PDO $db,array $config,array $value): string {if(!function_exists('openssl_encrypt'))throw new IntegrationError('Enable the PHP OpenSSL extension for encrypted webhook settings.',503);$key=connection_key($db,$config,true);$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt(json_encode($value,JSON_THROW_ON_ERROR),'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);if($cipher===false)throw new IntegrationError('Webhook credential encryption failed.',503);return base64_encode(json_encode(['iv'=>base64_encode($iv),'tag'=>base64_encode($tag),'cipher'=>base64_encode($cipher)],JSON_THROW_ON_ERROR));}
function connection_decrypt(PDO $db,array $config,string $value): array {if(!function_exists('openssl_decrypt'))throw new IntegrationError('Enable the PHP OpenSSL extension for encrypted webhook settings.',503);$key=connection_key($db,$config);$data=json_decode(base64_decode($value,true)?:'',true);if(!is_array($data))throw new IntegrationError('Webhook credentials cannot be decoded.',503);$plain=openssl_decrypt(base64_decode($data['cipher']),'aes-256-gcm',$key,OPENSSL_RAW_DATA,base64_decode($data['iv']),base64_decode($data['tag']));if($plain===false)throw new IntegrationError('Webhook credentials cannot be decrypted. Restore the matching integration.key.',503);return json_decode($plain,true,512,JSON_THROW_ON_ERROR);}
function connection_token_create(PDO $db,array $user,array $input): array {
 if(!auth_policy($user['role'])['integrations'])throw new IntegrationError('Integration administrator permission required.',403);$type=$input['type']??'';if(!in_array($type,['api','mcp'],true))throw new IntegrationError('Choose an API or MCP token.');$name=integration_text($input,'name',80);$source=integration_text($input,'source',40);if(!preg_match('/^[a-z0-9_-]{1,40}$/',$source))throw new IntegrationError('Connection identifier must use lowercase letters, digits, underscores or hyphens.');
 $days=$input['expires_days']??90;if(!is_int($days)||$days<1||$days>365)throw new IntegrationError('Token expiry must be 1–365 days.');
 $policy=auth_policy($user['role']);$scopes=[];
 if($type==='api'){$scopes=$input['scopes']??[];if(!is_array($scopes)||!array_is_list($scopes)||!$scopes||array_diff($scopes,['clients','outreach']))throw new IntegrationError('Choose clients and/or outreach permissions.');}
 else{foreach(['read','write','delete'] as $access){$list=$input[$access]??[];if(!is_array($list)||!array_is_list($list)||array_diff($list,business_kinds()))throw new IntegrationError('Invalid MCP module permission.');$allowed=$access==='read'?$policy['read']:$policy['write'];if(array_diff($list,$allowed))throw new IntegrationError('Requested MCP permissions exceed your own account.',403);$scopes[$access]=array_values(array_unique($list));}if(!$scopes['read'])throw new IntegrationError('Choose at least one readable MCP module.');if(array_diff($scopes['write'],$scopes['read'])||array_diff($scopes['delete'],$scopes['write']))throw new IntegrationError('Write requires read access; delete requires write access for the same module.');}
 $id=bin2hex(random_bytes(16));$raw='ke_'.$type.'_'.$id.'_'.bin2hex(random_bytes(32));$data=['id'=>$id,'type'=>$type,'name'=>$name,'source'=>$source,'scopes'=>$scopes,'token_hash'=>hash('sha256',$raw),'owner_id'=>(string)$user['id'],'owner_version'=>(int)$user['session_version'],'expires_at'=>gmdate('Y-m-d\TH:i:s\Z',time()+$days*86400),'created_at'=>gmdate('Y-m-d\TH:i:s\Z'),'last_used_at'=>'','revoked_at'=>''];connection_put($db,'integration-token-'.$id,'integration_token',$data);unset($data['token_hash'],$data['_record_id'],$data['owner_version']);return ['token'=>$raw,'connection'=>$data];
}
function connection_auth(PDO $db,string $raw,string $type): array {
 if(!preg_match('/^ke_'.preg_quote($type,'/').'_([a-f0-9]{32})_[a-f0-9]{64}$/',$raw,$m))throw new IntegrationError('Invalid or expired connection token.',401);
 $q=$db->prepare("SELECT payload FROM records WHERE id=? AND kind='integration_token'");$q->execute(['integration-token-'.$m[1]]);$r=$q->fetch();$token=$r?json_decode($r['payload'],true):null;
 if(!$token||$token['type']!==$type||$token['revoked_at']!==''||strtotime($token['expires_at'])<=time()||!hash_equals($token['token_hash'],hash('sha256',$raw)))throw new IntegrationError('Invalid or expired connection token.',401);
 $q=$db->prepare('SELECT id,name,email,role,active,must_change_password,session_version FROM users WHERE id=?');$q->execute([$token['owner_id']]);$owner=$q->fetch();if(!$owner||!$owner['active']||$owner['must_change_password']||(int)$owner['session_version']!==$token['owner_version']||!auth_policy($owner['role'])['integrations'])throw new IntegrationError('The token owner changed or lost access. Create a new token with an active administrator.',401);
 $q=$db->prepare("UPDATE records SET payload=JSON_SET(payload,'$.last_used_at',?) WHERE id=? AND kind='integration_token'");$q->execute([gmdate('Y-m-d\TH:i:s\Z'),'integration-token-'.$token['id']]);$token['owner']=$owner;return $token;
}
function connection_rate(PDO $db,string $source,int $max=120): void {$bucket=(int)floor(time()/60);$q=$db->prepare('INSERT INTO integration_rate_limits(source,minute_bucket) VALUES(?,?) ON DUPLICATE KEY UPDATE requests=requests+1');$q->execute([$source,$bucket]);$q=$db->prepare('SELECT requests FROM integration_rate_limits WHERE source=? AND minute_bucket=?');$q->execute([$source,$bucket]);if((int)$q->fetchColumn()>$max){header('Retry-After: 60');throw new IntegrationError('Connection request limit exceeded.',429);}}
function integration_runtime_config(PDO $db,array $config): array {
 $config['webhooks']=[];foreach(connection_rows($db,'integration_webhook') as $row){$value=['active'=>(bool)$row['active'],'name'=>$row['name'],'version'=>$row['version'],'host'=>$row['host'],'problem'=>''];try{$value=array_merge($value,connection_decrypt($db,$config,$row['encrypted']));}catch(IntegrationError $e){$value['active']=false;$value['problem']=$e->getMessage();}$config['webhooks'][$row['id']]=$value;}
 if(!empty($config['email_destination']['url']))$config['email_destination']['version']='legacy-'.hash('sha256',$config['email_destination']['url'].'\0'.($config['email_destination']['bearer_token']??''));return $config;
}
function connection_delivery_status(string $status): string{return ['queued'=>'pending','waiting_retry'=>'retry','sending'=>'processing'][$status]??$status;}
function connection_destination(array $config,string $id): array {if($id==='email'&&!empty($config['email_destination']['url']))return $config['email_destination'];$d=$config['webhooks'][$id]??null;if(!$d||!$d['active'])throw new IntegrationError(!empty($d['problem'])?$d['problem']:'Webhook is disabled or missing.',409);return $d;}
function connection_webhook_save(PDO $db,array $config,array $user,array $input): array {
 if(!auth_policy($user['role'])['integrations'])throw new IntegrationError('Integration administrator permission required.',403);$id=$input['id']??bin2hex(random_bytes(16));if(!is_string($id)||!preg_match('/^[a-f0-9]{32}$/',$id))throw new IntegrationError('Invalid webhook ID.');$name=integration_text($input,'name',80);$url=integration_text($input,'url',2000);$active=$input['active']??true;if(!is_bool($active))throw new IntegrationError('Invalid webhook status.');$p=parse_url($url);$destination=['url'=>$url,'allowed_hosts'=>[strtolower($p['host']??'')]];integration_target($destination,false);
 $q=$db->prepare("SELECT payload FROM records WHERE id=? AND kind='integration_webhook'");$q->execute(['integration-webhook-'.$id]);$old=$q->fetch();$old=$old?json_decode($old['payload'],true):null;$secret=integration_text($input,'bearer_token',2000,false);if(strpbrk($secret,"\r\n")!==false)throw new IntegrationError('Invalid webhook credential.');
 if($secret===''&&$old&&empty($input['clear_secret']))$secret=connection_decrypt($db,$config,$old['encrypted'])['bearer_token']??'';
 $destination['bearer_token']=$secret;$row=['id'=>$id,'name'=>$name,'host'=>$p['host'],'active'=>$active,'has_secret'=>$secret!=='','version'=>bin2hex(random_bytes(16)),'encrypted'=>connection_encrypt($db,$config,$destination),'created_by'=>(string)$user['id'],'created_at'=>$old['created_at']??gmdate('c'),'updated_at'=>gmdate('c'),'last_test'=>null];connection_put($db,'integration-webhook-'.$id,'integration_webhook',$row);return ['id'=>$id];
}
